  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户健康记录主键',
  `user_id` int(11) NULL DEFAULT NULL COMMENT '用户ID',
  `health_model_config_id` int(11) NULL DEFAULT NULL COMMENT '健康模型ID',
